/**
 * Model layouts: any model's weight matrices as slabs in 3D, stacked in
 * name-derived layout order or unstacked into one column per block. Catalog
 * models come from their safetensors headers alone (shapes, no weights),
 * generated by packages/nn/scripts/catalog_model_shapes.ts. A toy MLP is created
 * and run on the GPU, and a .safetensors file you open is drawn from its real
 * values when it fits, or from its header when it does not.
 */
import {
  type GpuTensor,
  layoutFromNames,
  layoutParameters,
  type ModelLayout,
  NnRuntime,
  parseSafetensors,
  readSafetensorsHeader,
  safetensorsHeaderLength,
  type Tensor,
  tensor,
} from "@molgpu/nn";
import catalogUrl from "./models/catalog.json?url";
import { pageDevice } from "../demos/viewer.tsx";
import type { Experiment } from "../pages/experiments.tsx";
import {
  shapeOnly,
  type StackStage,
  WeightStack,
} from "./weights/weight-stack.ts";

/** One entry of catalog.json, written by scripts/catalog_model_shapes.ts. */
interface CatalogModel {
  readonly id: string;
  readonly source: string;
  /** Tensors in the checkpoint, before collapsing experts. */
  readonly tensors: number;
  /** Checkpoint size in bytes, as stored (quantized). */
  readonly bytes: number;
  /** Weights in the layout's matrices, counting every expert. */
  readonly parameters: number;
  readonly dtypes: readonly string[];
  readonly stages: ModelLayout["stages"];
}

const TOY = "toy-mlp";
/** Files up to this size are parsed and uploaded; larger ones are read for their header only. */
const UPLOAD_LIMIT = 256 * 2 ** 20;

const count = (n: number) =>
  n >= 1e9
    ? `${(n / 1e9).toFixed(2)}B`
    : n >= 1e6
    ? `${(n / 1e6).toFixed(1)}M`
    : `${(n / 1e3).toFixed(1)}K`;

let seed = 1;
const random = (shape: number[], scale: number): Tensor => {
  const t = tensor(shape);
  for (let i = 0; i < t.data.length; i++) {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    t.data[i] = (seed / 2 ** 32 * 2 - 1) * scale;
  }
  return t;
};

const maxAbs = (values: Float32Array) =>
  values.reduce((m, v) => Math.max(m, Math.abs(v)), 0) || 1;

/** A model on the GPU: its stages with real buffers, owned by `runtime`. */
interface Loaded {
  readonly stages: StackStage[];
  readonly layout: ModelLayout;
  readonly runtime: NnRuntime | null;
  readonly note: string;
}

/** Upload named tensors and describe them as stages coloured from their buffers. */
async function upload(
  device: GPUDevice,
  weights: ReadonlyMap<string, Tensor>,
  layout: ModelLayout,
): Promise<{
  runtime: NnRuntime;
  gpu: Map<string, GpuTensor>;
  stages: StackStage[];
  skipped: number;
  summarized: number;
}> {
  const runtime = new NnRuntime(device);
  const gpu = new Map<string, GpuTensor>();
  const limit = device.limits.maxStorageBufferBindingSize;
  let skipped = 0;
  let summarized = 0;
  const stages: StackStage[] = [];
  try {
    for (const { label, matrices } of layout.stages) {
      const entries = [];
      for (const { name, shape } of matrices) {
        const t = weights.get(name)!;
        if (t.data.byteLength > device.limits.maxBufferSize) {
          skipped++;
          entries.push({ name, shape });
          continue;
        }
        const source = runtime.upload(t, name);
        if (t.data.byteLength > limit) {
          const summary = runtime.tileMeanAbs(source);
          const values = await runtime.read(summary) as Float32Array;
          runtime.release(source);
          summarized++;
          entries.push({
            name,
            shape,
            buffer: summary.buffer,
            values,
            scale: maxAbs(values),
            tileSize: 32,
          });
        } else {
          gpu.set(name, source);
          entries.push({
            name,
            shape,
            buffer: source.buffer,
            values: t.data,
            scale: maxAbs(t.data),
          });
        }
      }
      stages.push({ label, matrices: entries });
    }
    return { runtime, gpu, stages, skipped, summarized };
  } catch (error) {
    runtime.destroy();
    throw error;
  }
}

/** A random GELU MLP, created and run on the GPU. */
async function toyMlp(device: GPUDevice, widths: number[]): Promise<Loaded> {
  if (widths.length < 2 || widths.some((w) => !(w >= 1 && w <= 4096))) {
    throw new Error("widths: two or more sizes from 1 to 4096");
  }
  const weights = new Map<string, Tensor>();
  for (let i = 0; i + 1 < widths.length; i++) {
    // He-style scale so activations stay O(1) through the layers.
    const scale = Math.sqrt(6 / widths[i]);
    weights.set(
      `layers.${i}.weight`,
      random([widths[i + 1], widths[i]], scale),
    );
    weights.set(`layers.${i}.bias`, random([widths[i + 1]], 0.1));
  }
  const layout = layoutFromNames(weights, { collapseCopies: false });
  const { runtime, gpu, stages } = await upload(device, weights, layout);
  // Run a batch through the same buffers the view binds; biases are 1-D, so
  // the layout leaves them out and they are uploaded here.
  const bias = (i: number) =>
    runtime.upload(weights.get(`layers.${i}.bias`)!, `layers.${i}.bias`);
  let x = runtime.upload(random([16, widths[0]], 1), "input");
  for (let i = 0; i + 1 < widths.length; i++) {
    x = runtime.linear(
      x,
      gpu.get(`layers.${i}.weight`)!,
      bias(i),
      i + 2 < widths.length ? "gelu" : "none",
    );
  }
  const out = await runtime.read(x) as Float32Array;
  const mean = out.reduce((a, b) => a + b, 0) / out.length;
  return {
    stages,
    layout,
    runtime,
    note: `Created on the GPU and run on a batch of 16: output [16 × ${
      widths.at(-1)
    }], mean ${mean.toFixed(3)}, max |y| ${maxAbs(out).toFixed(3)}.`,
  };
}

/** A local .safetensors file: real values when small enough, else its header. */
async function openFile(device: GPUDevice, file: File): Promise<Loaded> {
  const prefix = new Uint8Array(await file.slice(0, 8).arrayBuffer());
  const length = safetensorsHeaderLength(prefix);
  if (file.size > UPLOAD_LIMIT) {
    const header = readSafetensorsHeader(
      new Uint8Array(await file.slice(0, 8 + length).arrayBuffer()),
    );
    const layout = layoutFromNames(header);
    return {
      stages: shapeOnly(layout),
      layout,
      runtime: null,
      note: `${file.name}: ${
        (file.size / 2 ** 30).toFixed(2)
      } GiB, read its ${length}-byte header only.`,
    };
  }
  const weights = parseSafetensors(new Uint8Array(await file.arrayBuffer()));
  const layout = layoutFromNames(weights, { collapseCopies: false });
  const { runtime, stages, skipped, summarized } = await upload(
    device,
    weights,
    layout,
  );
  return {
    stages,
    layout,
    runtime,
    note: `${file.name}: values uploaded to the GPU${
      summarized
        ? `; ${summarized} matrices use GPU 32 × 32 mean |w| tiles`
        : ""
    }${
      skipped ? `; ${skipped} matrices exceed maxBufferSize, shapes only` : ""
    }.`,
  };
}

const STYLE = `
  .experiment-canvas:has(.models-layout) { height: auto; overflow: visible; background: none; touch-action: auto; }
  .models-layout { display: grid; grid-template-columns: minmax(0, 1fr) 290px; gap: .75rem; color: #dbe4f3; font-size: .85rem; }
  .models-view { position: relative; height: clamp(420px, 66vh, 760px); border-radius: 12px; overflow: hidden; background: #02040a; }
  .models-view canvas { width: 100%; height: 100%; display: block; cursor: grab; touch-action: none; }
  .models-side { min-width: 0; background: #0a1220; border: 1px solid #1d2a3f; border-radius: 12px; padding: .7rem .8rem; display: grid; grid-template-columns: minmax(0, 1fr); gap: .5rem; align-content: start; }
  .models-side label:not([hidden]) { min-width: 0; display: flex; gap: .5rem; align-items: center; justify-content: space-between; }
  .models-layout select, .models-layout input[type=text], .models-layout button { font: inherit; color: inherit; background: #15213a; border: 1px solid #33476a; border-radius: 4px; padding: .15rem .4rem; min-width: 0; }
  .models-layout button { position: static; cursor: pointer; }
  .models-side select, .models-side input { flex: 1; min-width: 0; width: 0; }
  .models-stats { color: #93a4bf; margin: 0; line-height: 1.45; overflow-wrap: anywhere; }
  .models-stats a { color: #9fe3d8; word-break: break-all; }
  .weights-stage { position: absolute; transform: translate(-50%, -100%); pointer-events: none; padding: .05rem .4rem; border-radius: 4px; background: #050a16bb; color: #9fe3d8; font-size: .72rem; font-weight: 600; white-space: nowrap; }
  .models-tip { z-index: 1; position: absolute; pointer-events: none; max-width: calc(100% - 16px); overflow-wrap: anywhere; padding: .2rem .45rem; border-radius: 4px; background: #050a16ee; border: 1px solid #33476a; font-size: .75rem; }
  @media (max-width: 760px) { .models-layout { grid-template-columns: minmax(0, 1fr); } }
`;

export const experiment: Experiment = {
  title: "Model layouts",
  summary:
    "Any model's weight matrices as 3D slabs that stack and unstack: a catalog read from safetensors headers (ESM-2, GPT-2, Qwen, Mistral…), a toy MLP created on the GPU, or your own .safetensors file.",
  mount(host, params) {
    let live = true;
    let generation = 0;
    let stack: WeightStack | null = null;
    let runtime: NnRuntime | null = null;
    let catalog: CatalogModel[] = [];
    let file: File | null = null;

    const layout = document.createElement("div");
    layout.className = "models-layout";
    layout.innerHTML = `<style>${STYLE}</style>
      <div class="models-view"><canvas data-stack-canvas></canvas><div class="models-tip" data-tip hidden></div></div>
      <div class="models-side">
        <label>Model <select data-model-picker aria-label="Model"></select></label>
        <label data-widths-row hidden>Widths <input type="text" data-widths value="64, 256, 256, 128, 10" aria-label="Layer widths"></label>
        <label>Open <input type="file" accept=".safetensors" data-file aria-label="Open a safetensors file"></label>
        <label>Spacing <input type="range" data-gap min="0.1" max="3" step="0.05" value="0.6" aria-label="Stack spacing"></label>
        <button type="button" data-stack>Unstack</button>
        <p class="models-stats" data-stats>Loading the catalog…</p>
        <p class="models-stats">Width = columns, height = rows, to scale within each model. Checkpoint axes are preserved (FP4 unpacked); input/output roles depend on the model. Grouping follows tensor names, not a verified forward pass.</p>
        <p class="models-stats">Coloured slabs read GPU values. Matrices above the storage binding limit use snapshot 32 × 32 mean |w| tiles, not signed weights. Tinted slabs are shapes only. Drag to orbit, scroll to zoom.</p>
      </div>`;
    host.append(layout);
    const $ = <T extends Element>(selector: string) =>
      layout.querySelector<T>(selector)!;
    const picker = $<HTMLSelectElement>("[data-model-picker]");
    const widths = $<HTMLInputElement>("[data-widths]");
    const widthsRow = $<HTMLElement>("[data-widths-row]");
    const stats = $<HTMLElement>("[data-stats]");
    const stackButton = $<HTMLButtonElement>("[data-stack]");
    const gap = $<HTMLInputElement>("[data-gap]");
    stackButton.onclick = () => {
      if (stack) {
        stackButton.textContent = stack.toggle() === "stacked"
          ? "Unstack"
          : "Stack";
      }
    };
    gap.oninput = () => stack?.setGap(Number(gap.value));

    const teardown = () => {
      stack?.destroy();
      stack = null;
      runtime?.destroy();
      runtime = null;
    };

    const show = (device: GPUDevice, loaded: Loaded, source: string) => {
      runtime = loaded.runtime;
      stack = new WeightStack(
        device,
        $("[data-stack-canvas]"),
        $("[data-tip]"),
        loaded.stages,
      );
      stack.setGap(Number(gap.value));
      stackButton.textContent = "Unstack";
      const matrices = loaded.layout.stages.flatMap((s) => s.matrices);
      const largest = matrices.reduce(
        (a, m) => m.shape[0] * m.shape[1] > a.shape[0] * a.shape[1] ? m : a,
      );
      stats.innerHTML =
        `${source}<br>${loaded.layout.stages.length} stages · ${matrices.length} matrices · ${
          count(layoutParameters(loaded.layout))
        } weights in matrices<br>Largest: ${largest.name} [${
          largest.shape.join(" × ")
        }]<br>${loaded.note}`;
      host.dataset.model = "ready";
    };

    const load = () => {
      const request = ++generation;
      teardown();
      const id = picker.value;
      widthsRow.hidden = id !== TOY;
      host.dataset.model = "loading";
      void pageDevice().then(async (device) => {
        let loaded: Loaded, source: string;
        if (id === TOY) {
          loaded = await toyMlp(
            device,
            widths.value.split(/[,\s]+/).filter(Boolean).map(Number),
          );
          source = "Toy MLP";
        } else if (id === "file" && file) {
          loaded = await openFile(device, file);
          source = "Local file";
        } else {
          const model = catalog.find((m) => m.id === id)!;
          const layoutValue = { stages: model.stages };
          const experts = model.stages.flatMap((st) => st.matrices)
            .reduce((m, x) => Math.max(m, x.count ?? 1), 1);
          loaded = {
            stages: shapeOnly(layoutValue),
            layout: layoutValue,
            runtime: null,
            note:
              `Shapes from ${model.tensors.toLocaleString()} tensor headers (${
                (model.bytes / 2 ** 30).toFixed(1)
              } GiB stored as ${model.dtypes.join(", ")}).${
                experts > 1
                  ? ` Mixture of experts: up to ${experts} copies per matrix, drawn as thicker slabs; scales dropped, FP4 shown unpacked.`
                  : ""
              }`,
          };
          source = model.source.startsWith("https://")
            ? `<a href="${model.source}" target="_blank" rel="noopener">${model.id}</a>`
            : model.id;
        }
        if (!live || request !== generation) {
          loaded.runtime?.destroy();
          return;
        }
        show(device, loaded, source);
      }).catch((error) => {
        if (!live || request !== generation) return;
        host.dataset.model = "error";
        stats.textContent = String(error);
      });
    };

    picker.onchange = load;
    widths.onchange = load;
    $<HTMLInputElement>("[data-file]").onchange = (event) => {
      file = (event.target as HTMLInputElement).files?.[0] ?? null;
      if (!file) return;
      if (!picker.querySelector("option[value=file]")) {
        picker.append(new Option("Opened file", "file"));
      }
      picker.value = "file";
      load();
    };

    void fetch(catalogUrl).then((r) => r.json()).then(
      (data: { models: CatalogModel[] }) => {
        if (!live) return;
        catalog = data.models;
        picker.append(new Option("Toy MLP (create on the GPU)", TOY));
        for (const model of catalog) {
          picker.append(
            new Option(`${model.id} · ${count(model.parameters)}`, model.id),
          );
        }
        const wanted = params.get("model");
        picker.value = [TOY, ...catalog.map((m) => m.id)].includes(wanted ?? "")
          ? wanted!
          : catalog[0].id;
        load();
      },
    ).catch((error) => {
      stats.textContent = `Catalog: ${String(error)}`;
    });

    return () => {
      live = false;
      teardown();
      layout.remove();
    };
  },
};
